
UPDATE workflow_entity 
SET nodes = '[{"parameters": {"rule": {"interval": [{"field": "minutes", "minutesInterval": 5}]}}, "id": "node-trigger", "name": "Every 5 Minutes", "type": "n8n-nodes-base.scheduleTrigger", "typeVersion": 1.2, "position": [80, 300]}, {"parameters": {"method": "POST", "url": "http://fb-scraper:3000/scrape", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "Content-Type", "value": "application/json"}]}, "sendBody": true, "specifyBody": "json", "jsonBody": "={}", "options": {"timeout": 90000}}, "id": "node-scraper", "name": "Local Scraper: Scrape Group Posts", "type": "n8n-nodes-base.httpRequest", "typeVersion": 4.2, "position": [300, 300], "onError": "continueRegularOutput"}, {"parameters": {"jsCode": "// \u2500\u2500 B\u00f3c t\u00e1ch b\u00e0i vi\u1ebft & l\u1ecdc b\u00e0i vi\u1ebft trong 24h \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst allInputs = $input.all();\nlet rawPosts = [];\n\nfor (const item of allInputs) {\n  const data = item.json || {};\n  if (Array.isArray(data)) {\n    rawPosts.push(...data);\n  } else if (Array.isArray(data.posts)) {\n    rawPosts.push(...data.posts);\n  } else if (data.message || data.text || data.postId || data.id) {\n    rawPosts.push(data);\n  }\n}\n\nconst now = new Date();\nconst cutoff = new Date(now.getTime() - 24 * 60 * 60 * 1000);\n\nconst results = [];\nconst seenIds = new Set();\n\nfor (const post of rawPosts) {\n  const msg = String(post.message || post.text || ).trim();\n  if (!msg || msg.length < 10) continue;\n\n  const pId = String(post.postId || post.post_id || post.id || `fb_${Date.now()}_${Math.random()}`);\n  if (seenIds.has(pId)) continue;\n  seenIds.add(pId);\n\n  const postTime = post.created_time || post.createdAt || post.time;\n  const parsedTime = postTime ? new Date(postTime) : null;\n  if (parsedTime && !isNaN(parsedTime.getTime()) && parsedTime < cutoff) continue;\n\n  results.push({\n    post_id:      pId,\n    author:       String(post.author || post.authorName || post.username || Ng\u01b0\u1eddi d\u00f9ng Facebook),\n    message:      msg,\n    permalink:    String(post.permalink || post.url || https://www.facebook.com),\n    created_time: postTime || now.toISOString()\n  });\n}\n\n// Khi test trong n8n Editor ho\u1eb7c khi Scraper ch\u01b0a c\u00f3 b\u00e0i m\u1edbi -> T\u1ef1 \u0111\u1ed9ng n\u1ea1p Lead m\u1eabu \u0111\u1ec3 test\nif (results.length === 0 && ($execution?.mode === test || $execution?.mode === manual || $input.first()?.json?.__testTrigger)) {\n  results.push({\n    post_id:      `test_lead_${Date.now()}`,\n    author:       Kh\u00e1ch H\u00e0ng Test (Demo Lead),\n    message:      M\u00ecnh c\u1ea7n t\u00ecm team thi\u1ebft k\u1ebf website b\u00e1n h\u00e0ng th\u01b0\u01a1ng m\u1ea1i \u0111i\u1ec7n t\u1eed chuy\u00ean nghi\u1ec7p chu\u1ea9n SEO, t\u00edch h\u1ee3p chatbot AI t\u01b0 v\u1ea5n v\u00e0 c\u1ed5ng thanh to\u00e1n t\u1ef1 \u0111\u1ed9ng. Ng\u00e2n s\u00e1ch t\u1ea7m 15 - 25 tri\u1ec7u, ai l\u00e0m \u0111\u01b0\u1ee3c inbox m\u00ecnh nh\u00e9.,\n    permalink:    https://www.facebook.com/groups/1998083910206781/posts/demo_lead,\n    created_time: now.toISOString()\n  });\n}\n\nreturn results.map(p => ({ json: p }));"}, "id": "node-dedup", "name": "Dedup + Filter Recent", "type": "n8n-nodes-base.code", "typeVersion": 2, "position": [520, 300]}, {"parameters": {"conditions": {"options": {"caseSensitive": false, "leftValue": "", "typeValidation": "strict"}, "conditions": [{"id": "cond-kw", "leftValue": "={{ $json.message }}", "rightValue": "l\u00e0m web|thi\u1ebft k\u1ebf web|code web|thu\u00ea web|c\u1ea7n web|landing page|website|ecommerce|th\u01b0\u01a1ng m\u1ea1i \u0111i\u1ec7n t\u1eed|l\u1eadp tr\u00ecnh|app mobile|ph\u1ea7n m\u1ec1m|wordpress|shopify|ch\u1ea1y ads|ch\u1ea1y qu\u1ea3ng c\u00e1o|facebook ads|google ads|tiktok ads|performance marketing|marketing|t\u1ed1i \u01b0u ads", "operator": {"type": "string", "operation": "regex"}}], "combinator": "and"}}, "id": "node-keyword", "name": "Keyword Match?", "type": "n8n-nodes-base.if", "typeVersion": 2.2, "position": [740, 300]}, {"parameters": {"jsCode": "// \u2500\u2500 Chu\u1ea9n b\u1ecb d\u1eef li\u1ec7u Lead v\u00e0 m\u1eabu comment ch\u00e0o h\u00e0ng chuy\u00ean nghi\u1ec7p \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst matchedPosts = $input.all();\nconst professionalComment = Ch\u00e0o b\u1ea1n, b\u00ean m\u00ecnh chuy\u00ean thi\u1ebft k\u1ebf & ph\u00e1t tri\u1ec3n Website/Web App theo y\u00eau c\u1ea7u (UI/UX \u0111\u1ed9c quy\u1ec1n, chu\u1ea9n SEO Google, t\u1ed1c \u0111\u1ed9 t\u1ea3i c\u1ef1c nhanh, b\u00e0n giao 100% m\u00e3 ngu\u1ed3n & b\u1ea3o h\u00e0nh k\u1ef9 thu\u1eadt 12 th\u00e1ng).\\n\\n\ud83d\udcc1 Portfolio d\u1ef1 \u00e1n: company-plum-rho . vercel . app (b\u1ecf d\u1ea5u c\u00e1ch)\\n\ud83d\udcde Hotline/Zalo t\u01b0 v\u1ea5n: 0949.403.727\\n\\nB\u1ea1n check inbox ho\u1eb7c k\u1ebft b\u1ea1n Zalo \u0111\u1ec3 b\u00ean m\u00ecnh g\u1eedi b\u1ea3n demo giao di\u1ec7n v\u00e0 b\u1ea3ng b\u00e1o gi\u00e1 chi ti\u1ebft nh\u00e9!;\n\nconst results = [];\nfor (let i = 0; i < matchedPosts.length; i++) {\n  const post = matchedPosts[i]?.json || {};\n\n  results.push({\n    json: {\n      post_id:       post.post_id || `lead_${Date.now()}_${i}`,\n      author:        post.author || Ng\u01b0\u1eddi d\u00f9ng Facebook,\n      message:       post.message || ,\n      permalink:     post.permalink || https://www.facebook.com,\n      created_time:  post.created_time || new Date().toISOString(),\n      ai_comment:    professionalComment,\n      lead_score:    10,\n      score_reason:  B\u00e0i vi\u1ebft kh\u1edbp t\u1eeb kh\u00f3a t\u00ecm ki\u1ebfm d\u1ecbch v\u1ee5 website / digital,\n      score_badge:   \ud83d\udd25\n    }\n  });\n}\n\nreturn results;"}, "id": "node-fixed-comment", "name": "Prepare Lead & Fixed Comment", "type": "n8n-nodes-base.code", "typeVersion": 2, "position": [960, 200]}, {"parameters": {"operation": "executeQuery", "query": "=INSERT INTO stark_leads (post_id, author, message, permalink, ai_comment, lead_score, score_reason)\nVALUES (\n  {{ ($json.post_id || ).replace(//g, \"\") }},\n  {{ ($json.author || ).replace(//g, \"\") }},\n  {{ ($json.message || ).replace(//g, \"\") }},\n  {{ ($json.permalink || ).replace(//g, \"\") }},\n  {{ ($json.ai_comment || ).replace(//g, \"\") }},\n  {{ $json.lead_score || 10 }},\n  {{ ($json.score_reason || ).replace(//g, \"\") }}\n)\nON CONFLICT (post_id) DO NOTHING\nRETURNING id, post_id, author, message, permalink, ai_comment, lead_score, score_reason;"}, "id": "node-postgres", "name": "Save to stark_leads", "type": "n8n-nodes-base.postgres", "typeVersion": 2.5, "position": [1180, 200], "credentials": {"postgres": {"id": "stark-postgres-cred", "name": "n8n_stark_postgres"}}}, {"parameters": {"jsCode": "// \u2500\u2500 Ch\u1ec9 gi\u1eef l\u1ea1i c\u00e1c Lead TH\u1ef0C S\u1ef0 M\u1edaI (\u0111\u01b0\u1ee3c INSERT th\u00e0nh c\u00f4ng v\u00e0o DB) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst items = $input.all();\nconst newLeads = [];\n\nfor (const item of items) {\n  const data = item.json || {};\n  // Khi ON CONFLICT DO NOTHING x\u1ea3y ra, Postgres tr\u1ea3 v\u1ec1 { success: true } v\u00e0 KH\u00d4NG c\u00f3 data.id / data.post_id\n  if (data.id && data.post_id && data.permalink) {\n    newLeads.push(item);\n  }\n}\n\nreturn newLeads;"}, "id": "node-filter-new-leads", "name": "Filter New Leads Only", "type": "n8n-nodes-base.code", "typeVersion": 2, "position": [1350, 200]}, {"parameters": {"method": "POST", "url": "http://fb-scraper:3000/comment", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "Content-Type", "value": "application/json"}]}, "sendBody": true, "specifyBody": "json", "jsonBody": "={{ JSON.stringify({\n  postUrl: $json.permalink,\n  commentText: $json.ai_comment\n}) }}", "options": {"timeout": 60000}}, "id": "node-auto-comment", "name": "Auto Post Comment", "type": "n8n-nodes-base.httpRequest", "typeVersion": 4.2, "position": [1520, 200], "onError": "continueRegularOutput"}, {"parameters": {"jsCode": "// \u2500\u2500 Merge k\u1ebft qu\u1ea3 comment v\u1edbi d\u1eef li\u1ec7u Lead \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nconst commentOutputs = $input.all();\nconst preparedLeads = $(Filter New Leads Only).all();\n\nreturn commentOutputs.map((item, idx) => {\n  const lead = preparedLeads[idx]?.json || {};\n  const commentRes = item.json || {};\n  let errorMsg = ;\n  if (commentRes.error) {\n    errorMsg = typeof commentRes.error === object ? (commentRes.error.message || JSON.stringify(commentRes.error)) : String(commentRes.error);\n  } else if (commentRes.message && !commentRes.success) {\n    errorMsg = String(commentRes.message);\n  }\n  \n  let botStatus = \u2705 \u0110\u00e3 t\u1ef1 \u0111\u1ed9ng post comment;\n  if (commentRes.alreadyCommented) {\n    botStatus = \u2139\ufe0f B\u00e0i vi\u1ebft \u0111\u00e3 c\u00f3 b\u00ecnh lu\u1eadn t\u1eeb tr\u01b0\u1edbc (B\u1ecf qua);\n  } else if (!commentRes.success) {\n    botStatus = \u26a0\ufe0f  + (errorMsg || Ch\u01b0a t\u1ef1 \u0111\u1ed9ng comment \u0111\u01b0\u1ee3c);\n  }\n\n  return {\n    json: {\n      ...lead,\n      comment_success: Boolean(commentRes.success),\n      already_commented: Boolean(commentRes.alreadyCommented),\n      bot_status_text: botStatus\n    }\n  };\n});"}, "id": "node-merge-lead-comment", "name": "Merge Lead & Comment Result", "type": "n8n-nodes-base.code", "typeVersion": 2, "position": [1700, 200]}, {"parameters": {"method": "POST", "url": "https://slack.com/api/chat.postMessage", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "Authorization", "value": "=Bearer {{ $env.SLACK_BOT_TOKEN }}"}, {"name": "Content-Type", "value": "application/json"}]}, "sendBody": true, "specifyBody": "json", "jsonBody": "={{ JSON.stringify({\n  channel: $env.SLACK_CHANNEL_ID,\n  unfurl_links: false,\n  blocks: [\n    {\n      type: header,\n      text: { type: plain_text, text: `${$json.score_badge || \ud83d\udd25} Lead m\u1edbi \u2014 Kh\u1edbp t\u1eeb kh\u00f3a t\u00ecm ki\u1ebfm Website` }\n    },\n    {\n      type: section,\n      fields: [\n        { type: mrkdwn, text: `*\ud83d\udc64 T\u00e1c gi\u1ea3:*\\n${$json.author}` },\n        { type: mrkdwn, text: `*\ud83d\udcca Ph\u00e2n lo\u1ea1i:*\\n${$json.score_reason}` }\n      ]\n    },\n    {\n      type: section,\n      text: { type: mrkdwn, text: `*\ud83d\udcdd N\u1ed9i dung b\u00e0i:*\\n> ${String($json.message || ).replace(/\\n/g, \\n> ).substring(0, 400)}` }\n    },\n    { type: divider },\n    {\n      type: section,\n      text: { type: mrkdwn, text: `*\ud83d\udcac N\u1ed9i dung comment:*\\n\"\"\"${$json.ai_comment}\"\"\"\\n> \ud83e\udd16 *Tr\u1ea1ng th\u00e1i Bot:* ${$json.bot_status_text || ($json.comment_success ? \u2705 \u0110\u00e3 t\u1ef1 \u0111\u1ed9ng post comment : \u26a0\ufe0f L\u1ed7i comment)}` }\n    },\n    {\n      type: actions,\n      elements: [\n        {\n          type: button,\n          text: { type: plain_text, text: \ud83d\udd17 M\u1edf b\u00e0i Facebook },\n          url: $json.permalink || https://www.facebook.com,\n          action_id: open_fb_post,\n          style: primary\n        },\n        {\n          type: button,\n          text: { type: plain_text, text: \u23ed\ufe0f B\u1ecf qua },\n          action_id: skip,\n          value: JSON.stringify({ post_id: $json.post_id }),\n          style: danger\n        }\n      ]\n    }\n  ]\n}) }}", "options": {}}, "id": "node-slack", "name": "Send Slack Notification", "type": "n8n-nodes-base.httpRequest", "typeVersion": 4.2, "position": [1900, 200]}]'::json, 
